#!/usr/bin/env bash
# loop198: where a node's sixteen cores go. loop198 falsified "the harness is the limit": more flood workers make the
# fleet SLOWER (conc 64: window 1 435-443k at 0.366 s; 128: 397-401k at 0.40-0.41; 192: 380k at 0.43, the gate never
# open). Supply and the chain are not two resources: every node verifies every transaction on the cores its import and
# its build run on, and a deeper queue is more of that in flight. So the question is the per-node CPU budget: at ~11 us
# of ingest per transaction, 435k/s is ~5 of a node's 16 cores before a block is touched. This runner measures it:
# per-thread-name CPU of every execution layer, validator and the flood, every 5 s (threadcpu.py), on the chain
# configuration at conc 64 (the best of loop198), --pertx 12000 so window 3 does not run out of transactions.
cd /home/n42/src/n42/n42-rs
S=/home/n42/src/n42/n42-rs/target/fleet-runs
B=/data/blockchain/rust-fleet7-bench
NEW=/home/n42/src/n42/n42-rs/target/deferred/release
CLAIM=/data/blockchain/.box-claim-rust; CLAIM2=/data/blockchain/wr-logs/.box-claim-rust
cleanup() {
  rm -f $CLAIM $CLAIM2
  # The fleet this runner started goes with it. Killing the runner alone left
  # seven nodes and seven validators running for four and a half hours on
  # 2026-09-19: they held the box against this runner's own quiet check and
  # against whoever claimed it next.
  for p in $(pgrep -f '/n4[2] node'; pgrep -f 'h2_validato[r]'; pgrep -f 'tx_floo[d]'); do kill $p 2>/dev/null; done
}
trap cleanup EXIT
if ! grep -q 'fn push_reverted' crates/n42/tx-queue/src/lib.rs || ! grep -q 'fn fold_runs' bin/n42/src/follower_import.rs || ! grep -q 'fn commit_fcu_async' crates/n42/h2-execution/src/driver.rs || ! grep -q 'other_ms' bin/n42/src/follower_import.rs || ! grep -q 'fn own_block_imported' crates/n42/h2-execution/src/driver.rs || ! grep -q 'fn take_chained' crates/n42/h2-el-rpc/src/engine.rs || ! grep -q 'fn parent_executed_fields_or_built' crates/n42/engine-types/src/hotstuff_consensus.rs || ! grep -q 'fn state_at_soon' crates/n42/engine-types/src/direct_build.rs || ! grep -q 'fn convert_compact_body_to_block' crates/n42/engine-types/src/engine_validator.rs || ! grep -q 'fn get_by_hashes' crates/n42/tx-queue/src/lib.rs || ! grep -q 'fn index_and_stage' crates/n42/tx-queue/src/lib.rs || ! grep -q 'NEED_TXNS' crates/n42/h2-execution/src/raw_engine.rs || ! grep -q 'gate_forced' crates/n42/tx-ingest/src/lib.rs || ! grep -q 'fn import_for_validator' bin/n42/src/payload_serve.rs || ! grep -q 'FOREIGN_BODY' crates/n42/h2-execution/src/raw_engine.rs || ! grep -q 'fn note_reader_lag' crates/n42/qmdb-reth/src/node_state.rs || ! grep -q 'fn two_roads' bin/n42/src/follower_import.rs || ! grep -q 'fn follower_graft_stream' crates/n42/engine-types/src/parallel_transfer.rs || ! grep -q 'fn sort_reverts' crates/n42/engine-types/src/parallel_transfer.rs || ! grep -q 'fn graft_stream' crates/n42/engine-types/src/parallel_transfer.rs || ! grep -q 'install_staged' crates/n42/engine-types/src/payload.rs || ! grep -q 'fn direct_receipts_enabled' crates/n42/engine-types/src/payload.rs || ! grep -q 'tx_count += executed_count as u64' crates/n42/engine-types/src/payload.rs || ! grep -q 'fn batch_equation_holds' crates/n42/tx-types/src/alt_sig.rs || ! grep -q 'spawn_scoped(scope, root_job)' bin/n42/src/follower_import.rs; then echo "INSTRUMENTATION MISSING in the working tree; nothing built"; echo ALLDONE; exit 1; fi
T=$S/tests-loop198.log; : > $T
BUILD_FROM=$(date -u +%s)
tst() { echo "== $*" >> $T; nice -n 19 systemd-run --user --scope -q -p MemoryMax=40G -p MemorySwapMax=0 "$@" >> $T 2>&1; }
echo "tests from $(date +%H:%M) (no claim)"
for spec in "-p n42-engine-types --lib payload" "-p n42-tx-types --lib" "-p n42-qmdb-reth --lib" "-p n42-h2-execution --lib driver" "-p n42-h2-execution --test consensus_execution_loop" "-p n42 --lib payload_serve::tests" "-p n42 --lib follower_import" "-p n42-h2-el-rpc --lib" "-p n42-engine-types --lib engine_validator" "-p n42-h2-el-rpc --test build_chain" "-p n42-h2-consensus --lib header_profile" "-p n42-engine-types --lib chain_alias" "-p n42-engine-types --lib engine_validator" "-p n42-h2-consensus --lib compact_body" "-p n42-h2-node --lib body_channel" "-p n42-h2-net --lib rpc" "-p n42-engine-types --lib hotstuff_consensus" "-p n42-h2-execution --lib raw_engine" "-p n42-tx-ingest" "-p n42-tx-queue" "-p n42-h2-node --lib" "-p n42-h2-node --test four_node_fleet" "-p n42-h2-consensus --lib block_body"; do
  if ! tst cargo test -j8 --target-dir target/deferred $spec; then echo "TESTS FAILED: $spec (see $T)"; echo ALLDONE; exit 1; fi
done
if ! tst cargo clippy -j8 --target-dir target/deferred -p n42-h2-el-rpc -p n42-h2-consensus -p n42-h2-execution -p n42-h2-node -p n42-engine-types -p n42-qmdb-reth -p n42-tx-types -p n42 --lib --bins; then echo "CLIPPY FAILED (see $T)"; echo ALLDONE; exit 1; fi
echo "tests passed at $(date +%H:%M): $(grep -E '^test result:' $T | sed -E 's/test result: ok. ([0-9]+) passed.*/\1/' | paste -sd+ | bc) tests"
if ! nice -n 19 cargo build -j8 --release --target-dir target/deferred -p n42 --bin n42 -p n42-h2-node --example h2_validator --example tx_flood --example h2_keygen --example send_tx > $S/build-loop198.log 2>&1; then echo "BUILD FAILED"; echo ALLDONE; exit 1; fi
echo "built $(git rev-parse --short HEAD)+tree at $(date +%H:%M)"
WAITED_FROM=$(date -u +%s)
good() { local cpus; cpus=$(nproc)
  [ "$(pgrep -fc 'bin/n42-[a-z]+ --chai[n]')" = "0" ] && [ "$(pgrep -fc 'n42-[a-z0-9]+ --chai[n]')" = "0" ] \
    && [ "$(pgrep -fc 'n4[2] node')" = "0" ] && [ "$(pgrep -fc 'n42-dat[c]')" = "0" ] && [ "$(pgrep -fc 'eth-el-frame[d]')" = "0" ] \
    && { [ "$(pgrep -fc 'txfloo[d]')" = "0" ] || [ $(( $(date -u +%s) - ${WAITED_FROM:-0} )) -gt 600 ]; } \
    && [ "$(free -g | awk '/Mem:/{print $7}')" -ge 80 ] \
    && [ "$(awk '{printf "%d", $1}' /proc/loadavg)" -lt $(( cpus / 4 )) ]; }
theirs_claim() { local f n=""; for f in /data/blockchain/.box-claim-* /data/blockchain/wr-logs/.box-claim-*; do [ -e "$f" ] || continue; case "$f" in *box-claim-rust) continue;; esac; v=$(tr -c '0-9\n' ' ' < "$f" | tr -s ' ' '\n' | grep -E '^[0-9]+$' | sort -n | tail -1); [ -z "$v" ] && v=9999999999; n="$n $v"; done; echo $n | tr ' ' '\n' | grep -E '^[0-9]+$' | sort -n | tail -1; }
quiet() { local n=0; while [ $n -lt 3 ]; do [ -z "$(theirs_claim)" ] || return 1; good || return 1; n=$((n+1)); [ $n -lt 3 ] && sleep 30; done; return 0; }
mkdir -p /data/blockchain/wr-logs
echo "waiting for a quiet box from $(date +%H:%M)"
while true; do
  until quiet; do sleep 30; done
  mine=$(date -u +%s); echo "$mine" | tee $CLAIM > $CLAIM2
  sleep $((20 + RANDOM % 31))
  theirs=$(theirs_claim)
  [ -n "$theirs" ] && [ "$theirs" -lt "$mine" ] && [ $(( mine - theirs )) -gt 5400 ] && theirs=""
  if good && { [ -z "$theirs" ] || [ "$theirs" -gt "$mine" ]; }; then break; fi
  rm -f $CLAIM $CLAIM2; echo "stood down at $(date +%H:%M): another claim or the box got busy"; sleep 60
done
echo "claimed at $(date +%H:%M) ($mine): avail $(free -g | awk '/Mem:/{print $7}')G load $(awk '{print $1}' /proc/loadavg)"
CLAIMED_AT=$(date -u +%s)
if [ "$(stat -c %Y $NEW/n42)" -lt "$BUILD_FROM" ]; then echo "the binary predates this runner's build; released without a leg"; echo ALLDONE; exit 1; fi
export F7_LEADER_TENURE=16 F7_INGEST=1 F7_INGEST_ALL=1 F7_NO_TX_GOSSIP=1 N42_TX_INGEST_ASYNC=1
export F7_DIRECT_PUSH=1 F7_BLOCK_INTERVAL_MS=250 F7_SKIP_STALE_CHECK=1 F7_METRICS_BASE=19300 N42_TX_QUEUE=1
export N42_TX_INGEST_RECOVER_NICE=10 N42_TX_INGEST_RECOVER_PARALLEL=8 N42_TX_INGEST_DIRECT=1
elpid() { ps -eo pid,args | grep -E '/n4[2] node' | grep -E 'rust-fleet7-bench/node3' | awk '{print $1}' | head -1; }
sample() { local tag=$1
  for i in $(seq 1 44); do
    echo "$(date +%H:%M:%S) $(ps -eo rss,args | awk '/\/n4[2] node/{n++; s+=$1; if($1>mx)mx=$1; if(mn==0||$1<mn)mn=$1} /h2_validato[r]/{v+=$1} /tx_floo[d]/{f+=$1} END{printf "el_sum=%.1fG el_max=%.1fG el_min=%.1fG el_n=%d val_sum=%.1fG flood=%.1fG", s/1e6, mx/1e6, mn/1e6, n, v/1e6, f/1e6}') $(awk '/^MemAvailable|^MemFree|^AnonPages|^AnonHugePages|^Cached:|^Shmem:|^Slab:|^SUnreclaim|^PageTables|^Dirty:/{printf "%s%.1fG ", $1, $2/1e6}' /proc/meminfo) tmpfs=$(df --output=used -BG /tmp | tail -1 | tr -d ' ') compact_stall=$(awk '/^compact_stall/{print $2}' /proc/vmstat) flood_t=$(tail -1 $B/bench-$tag/flood.log 2>/dev/null | grep -oE '\+ *[0-9]+s' | tr -d ' ')"
    sleep 5
  done
}
median() { sort -n | awk '{a[NR]=$1} END{print (NR ? a[int(NR/2)+1] : "-")}'; }
run() { local tag=$1; shift
  local F7_GASPRICE_ARG="" F7_CONC_ARG=""; for kv in "$@"; do case "$kv" in F7_GASPRICE_ARG=*) F7_GASPRICE_ARG=${kv#*=};; F7_CONC_ARG=*) F7_CONC_ARG=${kv#*=};; esac; done
  ( n=0; until grep -q 'funding' $B/bench-$tag/flood.log 2>/dev/null; do sleep 1; n=$((n+1)); [ $n -gt 300 ] && exit 0; done; sample $tag ) > $S/mem-$tag.txt &
  ( n=0; until grep -q 'funding' $B/bench-$tag/flood.log 2>/dev/null; do sleep 1; n=$((n+1)); [ $n -gt 300 ] && exit 0; done; python3 $S/threadcpu.py 200 ) > $S/threadcpu-$tag.tsv 2>/dev/null &
  echo "leg $tag start $(date +%H:%M:%S) load $(awk '{print $1}' /proc/loadavg)"
  env "$@" timeout -k 30 600 scripts/fleet7-bench.sh --tag "$tag" --gasceil 3423000000 --senders 6000 --pertx 12000 --conc ${F7_CONC_ARG:-64} --rpcbatch 500 ${F7_GASPRICE_ARG:+--gasprice $F7_GASPRICE_ARG} > $S/bench-$tag.out 2>&1; echo "round $tag exit $? at $(date +%H:%M:%S)"
  for i in 0 1 2 3 4 5 6; do curl -s --max-time 5 127.0.0.1:$((19300 + i))/metrics > $B/bench-$tag/metrics-node$i.txt 2>/dev/null; done
  echo "$tag save stages (node0, seconds summed over the leg / count): $(python3 - "$B/bench-$tag/metrics-node0.txt" <<'PYEOF'
import re, sys
sums, counts = {}, {}
for line in open(sys.argv[1], errors='ignore'):
    m = re.match(r'([a-zA-Z_:]*save_blocks[a-zA-Z_]*|[a-zA-Z_:]*persistence[a-zA-Z_]*)_(sum|count)(\{[^}]*\})?\s+([0-9.eE+-]+)', line)
    if m:
        (sums if m.group(2) == 'sum' else counts)[m.group(1)] = float(m.group(4))
print('  '.join(f"{k.split('save_blocks')[-1].strip('_') or 'total'}={sums[k]:.1f}/{int(counts.get(k,0))}" for k in sorted(sums, key=lambda k: -sums[k])[:10]))
PYEOF
)"
  e=$(pgrep -f '/n4[2] node' | head -1); [ -n "$e" ] && echo "el binary: $(readlink /proc/$e/exe) env: $(tr '\0' '\n' < /proc/$e/environ | grep -E 'QMDB_READS|HASHED_TABLES|EXEC_ON_PARENT_OUTPUT|BLOCK_INTERVAL|RAYON_NUM_THREADS|PARALLEL_BUILD_THREADS|INGEST_RECOVER_PARALLEL|DIRECT_RECEIPTS|MALLOC_CONF' | paste -sd' ')"
  wait
  echo "$tag tc=$(cat $B/node*/v.log | grep -c 'TC formed') invalid_blocks=$(cat $B/node*/el.log | grep -c 'Encountered invalid block') incomplete=$(cat $B/node*/el.log | grep -c 'an incomplete execution result') gas_mismatch=$(cat $B/node*/el.log | grep -c 'gas used mismatch') direct_imports_failed=$(cat $B/node*/el.log | grep -c 'direct import failed') stuck_at_hashed_state=$(cat $B/node*/el.log | grep -c 'import_stage="hashed-state"') engine_idles_over_5s=$(cat $B/node*/el.log | grep -cE 'branch="orchestrator".*idle_before_ms=([5-9][0-9]{3}|[0-9]{5})') proposals_given_up=$(cat $B/node*/v.log | grep -c 'could not build a block to propose') tables_off_nodes=$(cat $B/node*/el.log | grep -c 'hashed state tables are not written') unanswered_reads=$(cat $B/node*/el.log | grep -c 'N42_HASHED_TABLES=off leaves no table') seal_first_total=$(cat $B/node*/el.log | grep -c 'seal-first build phases') seal_first_direct=$(cat $B/node*/el.log | grep 'seal-first build phases' | grep -c 'direct_receipts=true') direct_guard_errors=$(cat $B/node*/el.log | grep -c 'early seal that did not happen') commit_ms_median=$(cat $B/node*/el.log | grep 'seal-first build phases' | grep -oE 'par_commit_ms=[0-9]+' | cut -d= -f2 | median) fold_ms_median=$(cat $B/node*/el.log | grep 'seal-first build phases' | grep -oE 'par_fold_ms=[0-9]+' | cut -d= -f2 | median) sealed_at_ms_median=$(cat $B/node*/el.log | grep 'seal-first build phases' | grep -oE 'sealed_at_ms=[0-9]+' | cut -d= -f2 | median) state_ready_ms_median=$(cat $B/node*/el.log | grep 'seal-first build phases' | grep -oE 'state_ready_ms=[0-9]+' | cut -d= -f2 | median) build_total_ms_median=$(cat $B/node*/el.log | grep 'seal-first build phases' | grep -oE 'total_ms=[0-9]+' | cut -d= -f2 | median) recover_us_median=$(cat $B/node*/el.log | grep -oE 'recover_us_per_tx=[0-9]+' | cut -d= -f2 | median) par_exec_ms_median=$(cat $B/node*/el.log | grep 'seal-first build phases' | grep -oE 'par_exec_ms=[0-9]+' | cut -d= -f2 | median) par_exec_ms_median=$(cat $B/node*/el.log | grep 'seal-first build phases' | grep -oE 'par_exec_ms=[0-9]+' | cut -d= -f2 | median) giveback_filtered=$(cat $B/node*/el.log | grep 'offered again' | grep -oE 'mined=[0-9]+' | cut -d= -f2 | paste -sd+ | bc) giveback_offered_max=$(cat $B/node*/el.log | grep 'offered again' | grep -oE 'offered=[0-9]+' | cut -d= -f2 | sort -n | tail -1) seal_first=$(cat $B/node*/el.log | grep -c 'seal-first build phases') reader_lag_max=$(cat $B/node*/el.log | grep -oE 'reader_lag=[0-9]+' | cut -d= -f2 | sort -n | tail -1) reader_lag_warns=$(cat $B/node*/el.log | grep -c 'read view is falling behind\|falls behind\|reader lag') view_invalidated=$(cat $B/node*/el.log | grep -c 'read view is invalidated') el_sum_peak_g=$(grep -oE 'el_sum=[0-9.]+' $S/mem-$tag.txt | cut -d= -f2 | sort -n | tail -1) el_max_peak_g=$(grep -oE 'el_max=[0-9.]+' $S/mem-$tag.txt | cut -d= -f2 | sort -n | tail -1) val_sum_peak_g=$(grep -oE 'val_sum=[0-9.]+' $S/mem-$tag.txt | cut -d= -f2 | sort -n | tail -1) flood_peak_g=$(grep -oE 'flood=[0-9.]+' $S/mem-$tag.txt | cut -d= -f2 | sort -n | tail -1) two_roads_blocks=$(cat $B/node*/el.log | grep -c 'two roads: the execution ran beside the vote') two_roads_overlap_ms_median=$(cat $B/node*/el.log | grep 'two roads: the execution ran beside the vote' | grep -oE 'overlap_ms=[0-9]+' | cut -d= -f2 | median) exec_on_output_declined=$(cat $B/node*/el.log | grep -c "not executing on the parent's output") r1_collect_ms_median=$(cat $B/node*/v.log | sed -r 's/\x1b\[[0-9;]*m//g' | grep 'consensus_timing=leader' | grep -oE 'R1_collect=[0-9]+' | cut -d= -f2 | median) proposal_at_ms_median=$(cat $B/node*/v.log | sed -r 's/\x1b\[[0-9;]*m//g' | grep 'consensus_timing=leader' | grep -oE 'proposal=@[0-9]+' | tr -dc '0-9\n' | median) view_total_ms_median=$(cat $B/node*/v.log | sed -r 's/\x1b\[[0-9;]*m//g' | grep 'consensus_timing=leader' | grep -oE 'total=[0-9]+ms' | tr -dc '0-9\n' | median) import_exec_ms_median=$(cat $B/node*/el.log | grep 'handed to the engi