leg() {
  if [ $(( $(date -u +%s) - CLAIMED_AT )) -gt 4500 ]; then echo "leg loop198$1 skipped: 75 minutes of the claim used"; return; fi
  local tag=$1; shift
  run loop198$tag F7_EL_EXTRA="--builder.interval 60 --builder.deadline 3" N42_FAST_TRANSFER=1 N42_FOLLOWER_DIRECT_IMPORT=1 F7_SENDER_CACHE_MULT=4 N42_TX_QUEUE_BATCH=1024 N42_TX_QUEUE_DRAINER=1 F7_FLOOD_WINDOW=6 N42_TX_INGEST_RECOVER_PARALLEL=12 F7_BLOCK_INTERVAL_MS=350 "$@"
}
C='N42_BUILDER_PULLER=1024 N42_TX_QUEUE_RUN=64 MALLOC_CONF=thp:always N42_FOLLOWER_PARALLEL=1 TOKIO_WORKER_THREADS=8 F7_FLOOD_ALG=ed25519 N42_ALTSIG_SENDER_CACHE=4194304 N42_ED25519_BATCH=128'
R='N42_PARALLEL_BUILD=1 N42_FOLLOWER_GRAFT=1 F7_STRAGGLER_GRACE_MS=600 RAYON_NUM_THREADS=16 N42_BUILD_ON_SEAL=1 F7_LEADER_TENURE=64 N42_QMDB_RETAIN_DEPTH=16 N42_QMDB_ENTRY_FILE=1'
A2='MALLOC_CONF=thp:always,oversize_threshold:0,dirty_decay_ms:2000,background_thread:true'
D='N42_QMDB_READS=on N42_HASHED_TABLES=off F7_BLOCK_INTERVAL_MS=275 F7_GASPRICE_ARG=1000000000000000000000000 F7_SENDER_CACHE_MULT=1'
leg warm F7_BIN=$NEW $C $R $D $A2 "F7_EL_EXTRA=--builder.interval 60 --builder.deadline 3 --prune.transaction-lookup.full" N42_BUILD_CHAIN=1 N42_COMMIT_FCU_ASYNC=1 N42_BODY_ONCE=1 F7_BENCH_POOL_SLOTS=652000
leg T1 F7_BIN=$NEW $C $R $D $A2 "F7_EL_EXTRA=--builder.interval 60 --builder.deadline 3 --prune.transaction-lookup.full" N42_BUILD_CHAIN=1 N42_COMMIT_FCU_ASYNC=1 N42_BODY_ONCE=1 F7_BENCH_POOL_SLOTS=652000
leg T0 F7_BIN=$NEW $C $R $D $A2 "F7_EL_EXTRA=--builder.interval 60 --builder.deadline 3 --prune.transaction-lookup.full"
cleanup
echo "released at $(date +%H:%M)"
echo ALLDONE
